import React, { useRef, useState } from 'react';
import { Upload, File, X } from 'lucide-react';
import toast from 'react-hot-toast';
import { FileData } from '../../types';

interface FileUploadProps {
    onDataLoaded: (data: FileData) => void;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded }) => {
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [fileName, setFileName] = useState<string>('');
    const [fileContent, setFileContent] = useState<string>('');

    const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        setFileName(file.name);

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const content = e.target?.result as string;
                setFileContent(content);
                parseFileContent(content);
            } catch (error) {
                toast.error('Ошибка при чтении файла');
            }
        };

        reader.readAsText(file);
    };

    const parseFileContent = (content: string) => {
        try {
            const lines = content.trim().split('\n').map(line => line.trim()).filter(line => line);

            const n = parseInt(lines[0]);
            if (isNaN(n) || n <= 0 || n > 20) {
                throw new Error('Некорректная размерность (должна быть от 1 до 20)');
            }

            if (lines.length - 1 !== n) {
                throw new Error(`Ожидалось ${n} строк с данными, получено ${lines.length - 1}`);
            }

            const matrix: number[][] = [];
            const vector: number[] = [];

            for (let i = 1; i <= n; i++) {
                const values = lines[i].split(/\s+/).map(Number);

                if (values.length !== n + 1) {
                    throw new Error(`Строка ${i} должна содержать ${n + 1} чисел`);
                }

                if (values.some(isNaN)) {
                    throw new Error(`Строка ${i} содержит некорректные числа`);
                }

                const row = values.slice(0, n);
                const b = values[n];

                matrix.push(row);
                vector.push(b);
            }

            onDataLoaded({ matrix, vector });
            toast.success('Файл успешно загружен');

        } catch (error) {
            toast.error('Ошибка формата файла: ' + (error as Error).message);
            setFileName('');
            setFileContent('');
        }
    };

    const clearFile = () => {
        setFileName('');
        setFileContent('');
        if (fileInputRef.current) {
            fileInputRef.current.value = '';
        }
    };

    return (
        <div className="space-y-4">
            <div className="flex items-center gap-3">
                <button
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-2 px-4 py-2 bg-gray-100 text-gray-700 rounded-md hover:bg-gray-200 transition-colors"
                >
                    <Upload className="w-4 h-4" />
                    Выбрать файл
                </button>
                <input
                    ref={fileInputRef}
                    type="file"
                    accept=".txt,.dat,.csv"
                    onChange={handleFileUpload}
                    className="hidden"
                />

                {fileName && (
                    <div className="flex items-center gap-2 bg-blue-50 px-3 py-1 rounded-md">
                        <File className="w-4 h-4 text-blue-600" />
                        <span className="text-sm text-blue-700">{fileName}</span>
                        <button
                            onClick={clearFile}
                            className="ml-1 text-blue-500 hover:text-blue-700"
                        >
                            <X className="w-4 h-4" />
                        </button>
                    </div>
                )}
            </div>

            {fileContent && (
                <div className="bg-gray-50 rounded-md p-3">
                    <p className="text-xs font-medium text-gray-500 mb-2">Предпросмотр:</p>
                    <pre className="text-xs font-mono bg-white p-2 rounded border overflow-x-auto">
                        {fileContent}
                    </pre>
                </div>
            )}
        </div>
    );
};
